function zlG(k){try{if(typeof result!=='undefined'&&result&&result.get){var v=result.get(k);if(v!=null&&String(v)!==''){return String(v);}}}catch(e){}try{var m=source.getLoginInfoMap();if(m){var v2=m.get(k);if(v2!=null){return String(v2);}}}catch(e){}return '';}function zlP(v){v=String(v==null?'':v).trim();return (v==='null'?'':v);}function zlT(m){try{java.longToast(String(m));}catch(e){}}function zlL(m){try{java.log('Z-Library: '+m);}catch(e){}}function zlVW(s){s=String(s);var n=0;for(var i=0;i<s.length;i++){var c=s.charCodeAt(i);if(c>=0x1100&&(c<=0x115F||c===0x2329||c===0x232A||(c>=0x2E80&&c<=0xA4CF)||(c>=0xAC00&&c<=0xD7A3)||(c>=0xF900&&c<=0xFAFF)||(c>=0xFE30&&c<=0xFE6F)||(c>=0xFF00&&c<=0xFF60)||(c>=0xFFE0&&c<=0xFFE6))){n+=2;}else if((c>=0x2600&&c<=0x27BF)||(c>=0x2300&&c<=0x23FF)||(c>=0x2B00&&c<=0x2BFF)||(c>=0x2014&&c<=0x2015)||c===0x2026){n+=2;}else{n+=1;}}return n;} function zlSp(n){var t='';n=Math.round(Number(n)||0);if(n<0){n=0;}while(n>=2){t+='\u3000';n-=2;}if(n>0){t+='\u2002';}return t;} function zlPfx(){try{if(source){if(source.bookSourceName){return String(source.bookSourceName)+': ';}if(source.getTag){return String(source.getTag())+': ';}}}catch(e){}return '';} function zlT2(arr){var pfx=zlPfx(),W=zlVW(pfx),i,w;for(i=0;i<arr.length;i++){w=zlVW(arr[i]);if(w>W){W=w;}}var lines=[];for(i=0;i<arr.length;i++){lines.push(String(arr[i])+zlSp(W-zlVW(arr[i])));}zlT(zlSp(W-zlVW(pfx))+'\n'+lines.join('\n'));}function zlSt(){var o={};try{var h=String(source.getLoginHeader()||'');if(h){o=JSON.parse(h)||{};}}catch(e){o={};}return {cur:String(o.Cookie||''),cure:String(o['X-ZL-Cur']||''),alt:String(o['X-ZL-Alt']||''),alte:String(o['X-ZL-AltE']||'')};}function zlPut(cur,cure,alt,alte){var o={Cookie:String(cur||'')};if(cure){o['X-ZL-Cur']=String(cure);}if(alt){o['X-ZL-Alt']=String(alt);}if(alte){o['X-ZL-AltE']=String(alte);}try{source.putLoginHeader(JSON.stringify(o));zlL('已保存账号状态');}catch(e){zlL('保存账号状态失败 '+e);}}function zlCookie(u){return 'remix_userid='+u.id+'; remix_userkey='+u.remix_userkey;}function zlFill(email,pwd){try{var d={email:String(email==null?'':email)};if(pwd!=null){d.password=String(pwd);}java.upLoginData(JSON.parse(JSON.stringify(d)));zlL('界面已刷新');return true;}catch(e){zlL('界面刷新不支持 '+e);return false;}}function zlSaveForm(email,pwd){if(!email){return;}try{source.putLoginInfo(JSON.stringify({email:String(email),password:String(pwd==null?'':pwd)}));}catch(e){zlL('保存表单失败 '+e);}}function zlQuotaText(){try{var pj=JSON.parse(java.ajax('https://zh.zlib.bz/eapi/user/profile'));var u=pj&&pj.user;if(u&&u.id!=null){return '（'+(u.name||u.email||'')+' 今日 '+u.downloads_today+'/'+u.downloads_limit+'）';}}catch(e){}return '';}function zlDo(email,pwd){email=zlP(email);pwd=String(pwd==null?'':pwd);if(!email||!pwd){zlT('请先填写邮箱和密码');return null;}var body='email='+encodeURIComponent(email)+'&password='+encodeURIComponent(pwd);var opt='{"method":"POST","body":"'+body+'","headers":{"Content-Type":"application/x-www-form-urlencoded;charset=utf-8"}}';var r='';try{r=String(java.connect('https://zh.zlib.bz/eapi/user/login,'+opt).body());}catch(e){zlL('登录网络异常 '+e);zlT('❌网络异常（见日志）');return null;}var j={};try{j=JSON.parse(r);}catch(e){}if(j&&j.success==1&&j.user){return j.user;}zlL('登录失败 '+String(r).substring(0,200));zlT2(['❌ 登录失败',String((j&&j.error)?j.error:String(r).substring(0,48))]);return null;}function zlToggle(){try{return zlGo();}catch(e){zlL('切换异常 '+(e&&e.message?e.message:String(e)));zlT('❌切换出错（见日志）');return 'err';}}
function zlGo(){
var st=zlSt();
zlL('状态 cur='+st.cure+' alt='+st.alte);
var email=zlP(zlG('email')),pwd=zlP(zlG('password'));
if(!st.cur&&!st.cure){
if(!email||!pwd){zlT('请先填邮箱密码');return 'ok';}
var u=zlDo(email,pwd);
if(!u){return 'fail';}
zlPut(zlCookie(u),email,'','');
zlFill(email,'********');
zlSaveForm(email,'');
zlT2(['✅ 已登录','今日 '+u.downloads_today+'/'+u.downloads_limit]);
return 'ok';
}
if(!st.alt){
if(email&&pwd&&email!==st.cure){
var u2=zlDo(email,pwd);
if(!u2){return 'fail';}
zlPut(zlCookie(u2),email,st.cur,st.cure);
zlFill(email,'********');
zlSaveForm(email,'');
zlT2(['✅ 已记住 2 个号','再点一下即切换']);
return 'ok';
}
zlT2(['只有 1 个号','填另一个号再点']);
return 'ok';
}
var tgtE=st.alte,tgtC=st.alt;
zlPut(tgtC,tgtE,st.cur,st.cure);
zlSaveForm(tgtE,'');
var ui=zlFill(tgtE,'********');
var arr=['🔁 已切换',tgtE];
if(!ui){arr.push('※框未刷新 已切好');}
zlT2(arr);
return 'ok';
}
function login(){
var st=zlSt();
var email=zlP(zlG('email')),pwd=zlP(zlG('password'));
if(st.alte&&email===st.alte){
zlPut(st.alt,st.alte,st.cur,st.cure);
zlSaveForm(email,'');
zlFill(email,'********');
zlT2(['🔁 已切换',email]);
return 'ok';
}
if(st.cure&&email===st.cure){zlSaveForm(email,'');return 'keep';}
if(email&&pwd){
var u=zlDo(email,pwd);
if(!u){return 'fail';}
if(st.cure){zlPut(zlCookie(u),email,st.cur,st.cure);}else{zlPut(zlCookie(u),email,'','');}
zlSaveForm(email,'');
return 'ok';
}
return 'keep';
}
function zlCheck(){
var rep=[];var bad=false;
var loginOK=false,qline='',rline='',sOK=false,dOK=false,cOK=false,first=null;
try{
var u=null;
try{var pj=JSON.parse(java.ajax('https://zh.zlib.bz/eapi/user/profile'));u=(pj&&pj.user)||null;if(!u||!u.id){rep.push('profile: '+String(pj).substring(0,120));}}catch(e){rep.push('profile 异常: '+e);}
if(u&&u.id){
loginOK=true;
var used=Number(u.downloads_today),lim=Number(u.downloads_limit);
var left=(isNaN(used)||isNaN(lim))?null:(lim-used);
qline='✅ 登录\u3000'+(left==null?('今日 '+u.downloads_today+'/'+u.downloads_limit):('剩 '+left+' 次'));
rep.push('账号['+String(u.name||'')+'] <'+String(u.email||'')+'> 今日 '+u.downloads_today+'/'+u.downloads_limit+' 剩'+left);
if(left!=null&&left<=0){
var now=Date.now();var bj=new Date(now+8*3600000);
var rst=Date.UTC(bj.getUTCFullYear(),bj.getUTCMonth(),bj.getUTCDate(),5,0,0)-8*3600000;
if(now>=rst){rst+=86400000;}
var mm=Math.round((rst-now)/60000);if(mm<0){mm=0;}
rline='⏰ 重置\u3000还有 '+Math.floor(mm/60)+'h'+(mm%60)+'m';
}
}else{
qline='❌ 登录\u3000未登录';
}
var st=zlSt();
rep.push('已记住 主['+st.cure+'] 备['+st.alte+']');
try{
var body='message='+encodeURIComponent('book')+'&page=&limit=5';
var opt='{"method":"POST","body":"'+body+'","headers":{"Content-Type":"application/x-www-form-urlencoded;charset=utf-8"}}';
var sj=JSON.parse(java.ajax('https://zh.zlib.bz/eapi/book/search,'+opt));
var bs=(sj&&sj.books)||[];
if(bs.length){first=bs[0];}else{rep.push('搜索返回 0 条');}
sOK=!!first;
}catch(e){rep.push('搜索异常: '+e);}
if(first&&first.id&&first.hash){
try{var dj=JSON.parse(java.ajax('https://zh.zlib.bz/eapi/book/'+first.id+'/'+first.hash));dOK=!!(dj&&dj.book&&dj.book.dl);if(!dOK){rep.push('详情缺 dl');}}catch(e){rep.push('详情异常: '+e);}
try{java.ajax('https://zh.zlib.bz/papi/comments/book/'+first.id+'/0?limit=3');cOK=true;}catch(e){rep.push('评论异常: '+e);}
}else{rep.push('跳过详情/评论（搜索无结果）');}
rep.push('搜索'+(sOK?'OK':'FAIL')+' 详情'+(dOK?'OK':'FAIL')+' 评论'+(cOK?'OK':'FAIL'));
if(!loginOK||!sOK||!dOK||!cOK){bad=true;}
try{var lg=JSON.parse(String(cache.get('zl_log')||'')||'[]')||[];
if(lg&&lg.length){
var dt=[];for(var qi=lg.length-1;qi>=0;qi--){var x=lg[qi]||{};var dd=new Date(x.t||Date.now());
dt.push(('0'+dd.getHours()).slice(-2)+':'+('0'+dd.getMinutes()).slice(-2)+' 打开#'+(x.b||'?')+' 账号'+(x.a||'?')+' 已用'+(x.cur==null?'?':x.cur)+' 上次'+(x.prev==null?'-':x.prev)+' 归属'+(x.to||'-')+(x.hit?' → 判定下载':''));}
rep.push('下载检测('+lg.length+'):\n'+dt.join('\n'));
}else{rep.push('下载检测: 暂无记录');}}catch(e){}
if(bad){try{java.log('Z-Library 自检异常：\n'+rep.join('\n'));}catch(e){}}
var out=[];
if(!loginOK){out.push('—— 请先登录 ——');}
else if(!sOK||!dOK||!cOK){out.push('—— 有异常 ——');}
else{out.push('—— 全部正常 ——');}
out.push(qline);
out.push(sOK?'✅ 搜索\u3000正常':'❌ 搜索\u3000异常');
out.push(dOK?'✅ 详情\u3000正常':'❌ 详情\u3000异常');
out.push(cOK?'✅ 评论\u3000正常':'❌ 评论\u3000异常');
if(rline){out.push(rline);}
zlT2(out);
}catch(e){zlT('自检出错（详见日志）');zlL('自检异常 '+e);}
return 'checked';
}

